// Bài 8.3 — dựng INSERT
function buildInsert(table, data) {
  const cols = Object.keys(data).join(', ');
  const vals = Object.values(data).map((v) => "'" + v + "'").join(', ');
  return { sql: 'INSERT INTO ' + table + ' (' + cols + ') VALUES (' + vals + ')', params: [] };
}

