// Bài 8.3 — dựng UPDATE
function buildUpdate(table, changes, id, allowed) {
  const sets = Object.keys(changes).map((k) => k + ' = ?').join(', ');
  return { sql: 'UPDATE ' + table + ' SET ' + sets, params: Object.values(changes) };
}

