// Bài 8.3 — chuyển tiền
function transfer(accounts, fromId, toId, amount) {
  accounts.find((a) => a.id === toId).balance += amount;
  const from = accounts.find((a) => a.id === fromId);
  if (from.balance - amount < 0) throw new Error('CHECK constraint failed: balance >= 0');
  from.balance -= amount;
  return accounts;
}

