// Bài 8.3 — mọi ${giá trị} thành tham số; mảng thành (?, ?); mảnh sql`...` lồng được nhúng
const MARK = Symbol.for('sql');
function sql(strings, ...values) {
  let text = strings[0];
  const out = [];
  values.forEach((v, i) => {
    if (v && v[MARK] === true) {                             // mảnh SQL do chính sql`...` tạo ra
      text += v.text;
      out.push(...v.values);
    } else if (Array.isArray(v)) {
      if (v.length === 0) throw new RangeError('empty list in IN (...)');
      text += '(' + v.map(() => '?').join(', ') + ')';
      out.push(...v);
    } else {
      text += '?';                                           // chuỗi, số, null... luôn là tham số
      out.push(v);
    }
    text += strings[i + 1];
  });
  return { [MARK]: true, text, values: out };
}
